#!/usr/bin/env python3
"""Verify and transactionally import a complete exact-commit GitHub snapshot."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import stat
import subprocess
import sys
import tempfile
from datetime import datetime, timezone
from pathlib import Path, PurePosixPath
from typing import Any, Iterable

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_MANIFEST = ROOT / "input" / "upstream_reference" / "exact_snapshot" / "snapshot-manifest.json"
DEFAULT_BLOBS = DEFAULT_MANIFEST.parent / "blobs"
DEFAULT_UPSTREAM = ROOT / "source" / "upstream-snapshot"
DEFAULT_PRIMARY = ROOT / "source" / "primary"
DEFAULT_LOCK = ROOT / "source" / "SOURCE_LOCK.json"
DEFAULT_SOURCE_MANIFEST = ROOT / "source" / "SOURCE_MANIFEST.json"
EXPECTED_REPOSITORY = "pingdotgg/t3code"
EXPECTED_COMMIT = "c1ec1915fc16f3dc1ec5d47d9a97f6210a574526"
HEX40 = re.compile(r"^[0-9a-f]{40}$")
WINDOWS_DEVICES = {
    "CON", "PRN", "AUX", "NUL",
    *(f"COM{i}" for i in range(1, 10)),
    *(f"LPT{i}" for i in range(1, 10)),
}
ALLOWED_BLOB_MODES = {"100644", "100755", "120000"}


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def run(args: list[str], cwd: Path | None = None) -> str:
    proc = subprocess.run(args, cwd=cwd, text=True, capture_output=True, check=False)
    if proc.returncode != 0:
        raise RuntimeError(f"command failed ({proc.returncode}): {' '.join(args)}\n{proc.stdout}\n{proc.stderr}")
    return proc.stdout.strip()


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def git_object_sha(kind: str, data: bytes) -> str:
    return hashlib.sha1(kind.encode() + b" " + str(len(data)).encode() + b"\0" + data).hexdigest()


def git_blob_sha(data: bytes) -> str:
    return git_object_sha("blob", data)


def git_tree_sha(children: list[tuple[str, str, str]]) -> str:
    body = bytearray()
    for mode, name, sha in sorted(children, key=lambda item: item[1].encode("utf-8")):
        body.extend(mode.encode("ascii"))
        body.extend(b" ")
        body.extend(name.encode("utf-8"))
        body.extend(b"\0")
        body.extend(bytes.fromhex(sha))
    return git_object_sha("tree", bytes(body))


def validate_windows_component(component: str) -> None:
    trimmed = component.rstrip(" .")
    if not trimmed or trimmed != component:
        raise ValueError(f"Windows-unsafe path component: {component!r}")
    stem = trimmed.split(".", 1)[0].upper()
    if stem in WINDOWS_DEVICES:
        raise ValueError(f"Windows device path component: {component!r}")
    if any(ord(char) < 32 or char in '<>:"|?*' for char in component):
        raise ValueError(f"Windows-unsafe character in path component: {component!r}")


def validate_path(raw: str) -> PurePosixPath:
    if not raw or "\x00" in raw or \

 in raw:
        raise ValueError(f"unsafe path: {raw!r}")
    path = PurePosixPath(raw)
    if path.is_absolute() or ".." in path.parts or any(part in {"", "."} for part in path.parts):
        raise ValueError(f"unsafe path: {raw!r}")
    for component in path.parts:
        validate_windows_component(component)
    return path


def is_within(path: Path, root: Path) -> bool:
    try:
        path.resolve(strict=False).relative_to(root.resolve(strict=False))
        return True
    except ValueError:
        return False


def ensure_safe_symlink(path: PurePosixPath, target_bytes: bytes) -> str:
    try:
        target = target_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError(f"symlink target is not UTF-8 for {path}") from exc
    if not target or "\x00" in target or \

 in target:
        raise ValueError(f"unsafe symlink target for {path}: {target!r}")
    posix_target = PurePosixPath(target)
    if posix_target.is_absolute():
        raise ValueError(f"absolute symlink target for {path}: {target!r}")
    combined = path.parent
    parts: list[str] = []
    for part in (*combined.parts, *posix_target.parts):
        if part == ".":
            continue
        if part == "..":
            if not parts:
                raise ValueError(f"escaping symlink target for {path}: {target!r}")
            parts.pop()
        else:
            parts.append(part)
    return target


def detect_lfs_pointer(data: bytes) -> bool:
    return data.startswith(b"version https://git-lfs.github.com/spec/v1\n")


def resolve_blob_path(blobs_dir: Path, entry: dict[str, Any]) -> Path:
    relative = entry.get("blobPath")
    if relative is not None:
        path = blobs_dir / validate_path(str(relative))
    else:
        path = blobs_dir / str(entry["sha"])
    if not is_within(path, blobs_dir):
        raise ValueError(f"blob path escaped blob directory: {path}")
    return path


def normalize_entries(manifest: dict[str, Any], blobs_dir: Path) -> tuple[list[dict[str, Any]], dict[str, bytes]]:
    raw_entries = manifest.get("entries")
    if not isinstance(raw_entries, list) or not raw_entries:
        raise ValueError("snapshot manifest has no entries")
    entries: list[dict[str, Any]] = []
    blobs: dict[str, bytes] = {}
    case_map: dict[str, str] = {}
    paths: set[str] = set()
    for raw in raw_entries:
        if not isinstance(raw, dict):
            raise ValueError("invalid tree entry")
        path = validate_path(str(raw.get("path", "")))
        path_text = str(path)
        folded = path_text.casefold()
        if path_text in paths:
            raise ValueError(f"duplicate path: {path_text}")
        if folded in case_map and case_map[folded] != path_text:
            raise ValueError(f"case-colliding paths: {case_map[folded]} and {path_text}")
        paths.add(path_text)
        case_map[folded] = path_text
        kind = str(raw.get("type", ""))
        mode = str(raw.get("mode", ""))
        sha = str(raw.get("sha", ""))
        if kind not in {"blob", "tree", "commit"}:
            raise ValueError(f"unsupported object type for {path_text}: {kind}")
        if not HEX40.fullmatch(sha):
            raise ValueError(f"invalid object SHA for {path_text}")
        if kind == "commit" or mode == "160000":
            raise ValueError(f"submodule requires explicit handling: {path_text}")
        if kind == "tree":
            if mode != "040000":
                raise ValueError(f"invalid tree mode for {path_text}: {mode}")
            entries.append({"path": path, "type": kind, "mode": mode, "sha": sha})
            continue
        if mode not in ALLOWED_BLOB_MODES:
            raise ValueError(f"unsupported blob mode for {path_text}: {mode}")
        blob_path = resolve_blob_path(blobs_dir, raw)
        if not blob_path.is_file():
            raise ValueError(f"missing blob bytes for {path_text}: {blob_path}")
        data = blob_path.read_bytes()
        expected_size = raw.get("size")
        if expected_size is not None and int(expected_size) != len(data):
            raise ValueError(f"blob size mismatch for {path_text}")
        actual_sha = git_blob_sha(data)
        if actual_sha != sha:
            raise ValueError(f"Git blob SHA mismatch for {path_text}: expected {sha}, got {actual_sha}")
        if mode == "120000":
            ensure_safe_symlink(path, data)
        elif detect_lfs_pointer(data):
            raise ValueError(f"unresolved Git LFS pointer: {path_text}")
        blobs[sha] = data
        entries.append({
            "path": path,
            "type": kind,
            "mode": mode,
            "sha": sha,
            "size": len(data),
        })
    return entries, blobs


def verify_tree(entries: list[dict[str, Any]], expected_root: str) -> tuple[str, int]:
    explicit_tree_shas = {str(entry["path"]): entry["sha"] for entry in entries if entry["type"] == "tree"}
    directories: set[str] = {""}
    for entry in entries:
        path = entry["path"]
        current = path.parent
        while str(current) not in {"", "."}:
            directories.add(str(current))
            current = current.parent
        if entry["type"] == "tree":
            directories.add(str(path))
    computed: dict[str, str] = {}
    for directory in sorted(directories, key=lambda item: (item.count("/"), item), reverse=True):
        children: list[tuple[str, str, str]] = []
        directory_path = PurePosixPath(directory) if directory else PurePosixPath(".")
        for entry in entries:
            if entry["path"].parent == directory_path and entry["type"] == "blob":
                children.append((entry["mode"], entry["path"].name, entry["sha"]))
        child_dirs = {
            candidate for candidate in directories
            if candidate and PurePosixPath(candidate).parent == directory_path
        }
        for child in child_dirs:
            children.append(("40000", PurePosixPath(child).name, computed[child]))
        tree_sha = git_tree_sha(children)
        computed[directory] = tree_sha
        explicit = explicit_tree_shas.get(directory)
        if explicit is not None and explicit != tree_sha:
            raise ValueError(f"tree SHA mismatch for {directory}: expected {explicit}, got {tree_sha}")
    root = computed[""]
    if root != expected_root:
        raise ValueError(f"root tree SHA mismatch: expected {expected_root}, got {root}")
    return root, len(directories) - 1


def materialize(entries: list[dict[str, Any]], blobs: dict[str, bytes], target: Path) -> None:
    for entry in sorted(entries, key=lambda item: (len(item["path"].parts), str(item["path"]))):
        if entry["type"] == "tree":
            continue
        relative = Path(*entry["path"].parts)
        destination = target / relative
        if not is_within(destination, target):
            raise ValueError(f"materialization path escaped target: {relative}")
        destination.parent.mkdir(parents=True, exist_ok=True)
        data = blobs[entry["sha"]]
        if entry["mode"] == "120000":
            os.symlink(ensure_safe_symlink(entry["path"], data), destination)
        else:
            destination.write_bytes(data)
            destination.chmod(0o755 if entry["mode"] == "100755" else 0o644)


def write_source_manifest(entries: list[dict[str, Any]], target: Path, output: Path) -> tuple[str, dict[str, int]]:
    records: list[dict[str, Any]] = []
    stats = {"fileCount": 0, "symlinkCount": 0, "executableFileCount": 0}
    for entry in sorted((item for item in entries if item["type"] == "blob"), key=lambda item: str(item["path"])):
        path_text = str(entry["path"])
        path = target / Path(*entry["path"].parts)
        if entry["mode"] == "120000":
            target_value = os.readlink(path)
            data = target_value.encode("utf-8")
            kind = "symlink"
            stats["symlinkCount"] += 1
            record: dict[str, Any] = {
                "path": path_text,
                "kind": kind,
                "mode": entry["mode"],
                "gitBlobSha1": entry["sha"],
                "sha256": sha256_bytes(data),
                "sizeBytes": len(data),
                "symlinkTarget": target_value,
            }
        else:
            data = path.read_bytes()
            stats["fileCount"] += 1
            if entry["mode"] == "100755":
                stats["executableFileCount"] += 1
            record = {
                "path": path_text,
                "kind": "file",
                "mode": entry["mode"],
                "gitBlobSha1": entry["sha"],
                "sha256": sha256_bytes(data),
                "sizeBytes": len(data),
            }
        records.append(record)
    payload = {"schemaVersion": 2, "files": records}
    output.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
    digest = sha256_file(output)
    output.with_suffix(output.suffix + ".sha256").write_text(f"{digest}  {output.name}\n", encoding="ascii")
    return digest, stats


def copy_tree(source: Path, target: Path) -> None:
    shutil.copytree(source, target, symlinks=True, copy_function=shutil.copy2)


def atomic_replace(source: Path, target: Path) -> None:
    backup = target.with_name(target.name + ".previous")
    if backup.exists() or backup.is_symlink():
        if backup.is_dir() and not backup.is_symlink():
            shutil.rmtree(backup)
        else:
            backup.unlink()
    if target.exists() or target.is_symlink():
        target.replace(backup)
    source.replace(target)
    if backup.exists() or backup.is_symlink():
        if backup.is_dir() and not backup.is_symlink():
            shutil.rmtree(backup)
        else:
            backup.unlink()


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--manifest", type=Path, default=DEFAULT_MANIFEST)
    parser.add_argument("--blobs-dir", type=Path, default=DEFAULT_BLOBS)
    parser.add_argument("--upstream-output", type=Path, default=DEFAULT_UPSTREAM)
    parser.add_argument("--primary-output", type=Path, default=DEFAULT_PRIMARY)
    parser.add_argument("--source-lock", type=Path, default=DEFAULT_LOCK)
    parser.add_argument("--source-manifest", type=Path, default=DEFAULT_SOURCE_MANIFEST)
    parser.add_argument("--repository", default=EXPECTED_REPOSITORY)
    parser.add_argument("--commit", default=EXPECTED_COMMIT)
    args = parser.parse_args()

    manifest_path = args.manifest.resolve()
    blobs_dir = args.blobs_dir.resolve()
    if not manifest_path.is_file() or not blobs_dir.is_dir():
        raise SystemExit("snapshot manifest and blob directory are required")
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    if manifest.get("repository") != args.repository or manifest.get("commit") != args.commit:
        raise SystemExit("snapshot repository or commit does not match the requested authority")
    if manifest.get("treeTruncated") is not False:
        raise SystemExit("complete non-truncated GitHub tree evidence is required")
    tree_sha = manifest.get("tree")
    if not isinstance(tree_sha, str) or not HEX40.fullmatch(tree_sha):
        raise SystemExit("valid upstream tree SHA is required")
    parents = manifest.get("parents")
    if not isinstance(parents, list) or not all(isinstance(item, str) and HEX40.fullmatch(item) for item in parents):
        raise SystemExit("valid parent commit metadata is required")

    entries, blobs = normalize_entries(manifest, blobs_dir)
    verified_tree, directory_count = verify_tree(entries, tree_sha)

    temp_parent = args.upstream_output.resolve().parent
    temp_parent.mkdir(parents=True, exist_ok=True)
    with tempfile.TemporaryDirectory(prefix="verified-snapshot-", dir=temp_parent) as temporary:
        temp_root = Path(temporary)
        staged_upstream = temp_root / "upstream-snapshot"
        staged_primary = temp_root / "primary"
        staged_upstream.mkdir()
        materialize(entries, blobs, staged_upstream)
        copy_tree(staged_upstream, staged_primary)

        run(["git", "init", "-b", "build/t3-chatgpt-agent"], cwd=staged_primary)
        run(["git", "config", "user.name", "T3 ChatGPT Agent Builder"], cwd=staged_primary)
        run(["git", "config", "user.email", "t3-agent-builder@localhost"], cwd=staged_primary)
        run(["git", "config", "core.symlinks", "true"], cwd=staged_primary)
        run(["git", "add", "-A"], cwd=staged_primary)
        run(["git", "commit", "-m", f"import: verified pingdotgg/t3code snapshot at {args.commit}"], cwd=staged_primary)
        run(["git", "tag", f"upstream-snapshot-{args.commit}"], cwd=staged_primary)
        local_commit = run(["git", "rev-parse", "HEAD"], cwd=staged_primary)
        local_tree = run(["git", "rev-parse", "HEAD^{tree}"], cwd=staged_primary)
        if local_tree != verified_tree:
            raise RuntimeError(f"local import tree mismatch: expected {verified_tree}, got {local_tree}")
        run(["git", "fsck", "--full", "--strict"], cwd=staged_primary)
        if run(["git", "status", "--porcelain"], cwd=staged_primary):
            raise RuntimeError("local repository is dirty after import")

        staged_manifest = temp_root / "SOURCE_MANIFEST.json"
        manifest_digest, stats = write_source_manifest(entries, staged_upstream, staged_manifest)
        lock = {
            "schemaVersion": 2,
            "repository": args.repository,
            "requestedCommit": args.commit,
            "verifiedUpstreamCommit": args.commit,
            "verifiedUpstreamTree": verified_tree,
            "parentCommits": parents,
            "acquisitionMode": "github_exact_commit_snapshot",
            "originalGitDatabaseAvailable": False,
            "originalGitFsckPerformed": False,
            "snapshotTreeFullyEnumerated": True,
            "allBlobHashesVerified": True,
            "upstreamTreeReconstructedAndVerified": True,
            "localRepositoryFsckPassed": True,
            "localImportCommit": local_commit,
            "localImportTree": local_tree,
            "localBranch": "build/t3-chatgpt-agent",
            "localTag": f"upstream-snapshot-{args.commit}",
            "fileCount": stats["fileCount"],
            "directoryCount": directory_count,
            "symlinkCount": stats["symlinkCount"],
            "executableFileCount": stats["executableFileCount"],
            "manifestSha256": manifest_digest,
            "snapshotManifestSha256": sha256_file(manifest_path),
            "acquiredAt": utc_now(),
            "toolVersions": {
                "python": sys.version.split()[0],
                "git": run(["git", "--version"]),
            },
            "limitations": [
                "The original upstream Git object database and historical connectivity were unavailable.",
                "The source bytes and complete recursive tree were verified against the exact GitHub commit snapshot.",
                "History-dependent Git operations remain limited until an original Git bundle is obtained.",
            ],
        }
        staged_lock = temp_root / "SOURCE_LOCK.json"
        staged_lock.write_text(json.dumps(lock, indent=2) + "\n", encoding="utf-8")

        atomic_replace(staged_upstream, args.upstream_output.resolve())
        atomic_replace(staged_primary, args.primary_output.resolve())
        args.source_manifest.resolve().parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(staged_manifest, args.source_manifest.resolve())
        shutil.copy2(staged_manifest.with_suffix(staged_manifest.suffix + ".sha256"), args.source_manifest.resolve().with_suffix(args.source_manifest.suffix + ".sha256"))
        shutil.copy2(staged_lock, args.source_lock.resolve())

    print(f"Verified exact-commit snapshot imported: {args.commit} tree {verified_tree}")
    print(f"Local import repository: {args.primary_output.resolve()}")


if __name__ == "__main__":
    main()
